form:
{@body const [course,setCourse] = DIL.useState("")}
{@body const [notes,setNotes] = DIL.useState("")}
{@body const [date,setDate] = DIL.useState("")}
{@body const [scope,setScope] = DIL.useState("日")}
<form label="学习安排" onSubmit={() => GenUI.issueNewTurn("学习 " + course + "，备注 " + notes + "，日期 " + date + "，周期 " + scope)}>
  <grid columns={2} gap={3}>
    <input label="课程名称" value={course} onChange={setCourse} required maxLength={24}/>
    <date-picker label="学习日期" value={date} onChange={setDate} required min="2026-01-01" max="2026-12-31"/>
  </grid>
  <textarea label="备注" value={notes} onChange={setNotes}/>
  <segmented-control label="周期" value={scope} onChange={setScope} options={["日", "周", "月"]}/>
  {#if scope === "周"}<badge>按周安排</badge>{:else}<text>按所选周期安排</text>{/if}
  <button type="submit">提交学习安排</button>
</form>
